pub fn parse_bytes(text: &str) -> Result<Vec<u8>, String> {
    if text.trim().is_empty() { return Ok(vec![]); }
    text.split(',').map(|s| {let value=s.trim(); if value.is_empty() || !value.bytes().all(|b| b.is_ascii_digit()) {return Err("invalid".to_string());} value.parse::<u8>().map_err(|_| "invalid".to_string())}).collect()
}

